  using SrcType = typename internal::UnderlyingType<Src>::type;
  return __builtin_expect(!!((IsValueInRangeForNumericType<Dst>(value))), 1)
             ? static_cast<Dst>(static_cast<SrcType>(value))
             : CheckHandler::template HandleFailure<Dst>();
