  static_assert(
      static_cast<uint32_t>((-1) >> 31) == ~(0U),
      "implementation does not support assumed rightshift");
  static_assert(static_cast<uint32_t>((1) >> 31) == (0U),
                "implementation does not support assumed rightshift");


  return (static_cast<uint32_t>(value) << 1) ^
         static_cast<uint32_t>(value >> 31);
